#!/bin/sh
# Generated by FWShift: rows for the packet filter (and NAT) of a Phoenix Contact mGuard, added with gaiconfig.
# Read the report first: what is not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE            prints the gaiconfig calls; runs anywhere
#   sh THIS_FILE                      on the mGuard (SSH, as root or admin): adds the groups and rows
#   FWSHIFT_APPEND=yes sh THIS_FILE   also when the tables have rows: the new ones go after them
#
# Nothing is changed or deleted, and no interface, route or access to the mGuard is touched. Every call but the last
# writes with --silent; the last one reconfigures, and the rows take effect then. A call gaiconfig refuses stops the
# script: what was written before is stored but not active (the groups start with 'fws_', the rows' comments
# with the names of the rules); remove it in the web interface, or run the script again after fixing the cause.
set -u
DRY_RUN="${DRY_RUN:-}"
FWSHIFT_APPEND="${FWSHIFT_APPEND:-}"
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
gc() {
  if [ -n "$DRY_RUN" ]; then printf 'gaiconfig' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gaiconfig "$@" >/dev/null || fail "gaiconfig $*"
}
rows() {
  if [ -n "$DRY_RUN" ]; then echo 0; return 0; fi
  gaiconfig --get-rowcount "$1" || fail "gaiconfig --get-rowcount $1"
}
named() {
  [ -z "$DRY_RUN" ] && gaiconfig --get "$1" 2>/dev/null | grep -F -q "NAME = \"$2\""
}
if [ -z "$DRY_RUN" ] && ! command -v gaiconfig >/dev/null 2>&1; then fail "gaiconfig not found: run this on the mGuard"; fi
for t in FW_INCOMING FW_OUTGOING; do
  n=$(rows "$t")
  if [ "$n" != 0 ] && [ "$FWSHIFT_APPEND" != yes ]; then
    fail "$t has $n rows, which the mGuard would check before the new ones; nothing was written (FWSHIFT_APPEND=yes adds after them)"
  fi
done
named FW_GROUP_IP fws_DNS_src && fail 'an IP group named fws_DNS_src exists; nothing was written'
named FW_GROUP_IP fws_dns-servers && fail 'an IP group named fws_dns-servers exists; nothing was written'
named FW_GROUP_IP fws_admin-range && fail 'an IP group named fws_admin-range exists; nothing was written'
named FW_GROUP_IP fws_dmz-servers && fail 'an IP group named fws_dmz-servers exists; nothing was written'
named FW_GROUP_PORT fws_Web_out && fail 'a port group named fws_Web_out exists; nothing was written'
named FW_GROUP_IP fws_Guests_stay_out_dst && fail 'an IP group named fws_Guests_stay_out_dst exists; nothing was written'
named FW_GROUP_PORT fws_PLC_access && fail 'a port group named fws_PLC_access exists; nothing was written'
named FW_GROUP_IP fws_.updates.example.com && fail 'an IP group named fws_.updates.example.com exists; nothing was written'
named FW_GROUP_IP fws_Public_web_dst && fail 'an IP group named fws_Public_web_dst exists; nothing was written'
named FW_GROUP_PORT fws_app-ports && fail 'a port group named fws_app-ports exists; nothing was written'

# FW_GROUP_IP
N=$(rows FW_GROUP_IP)
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_DNS_src --set .COMMENT 'FWShift: lan-net, dmz-net'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.10.0.0/16
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.0.0/24
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_dns-servers --set .COMMENT 'FWShift: dns-servers'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 192.0.2.53-192.0.2.54
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_admin-range --set .COMMENT 'FWShift: admin-range'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.10.5.10-10.10.5.20
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_dmz-servers --set .COMMENT 'FWShift: dmz-servers'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.0.10
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.0.25
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 203.0.113.10
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_Guests_stay_out_dst --set .COMMENT 'FWShift: not dns-servers'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 0.0.0.0-192.0.2.52
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 192.0.2.55-255.255.255.255
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_.updates.example.com --set .COMMENT 'FWShift: .updates.example.com'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP updates.example.com
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_Public_web_dst --set .COMMENT 'FWShift: web-1, web-1_valid_address'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 10.20.0.10
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 203.0.113.10
N=$((N+1))

# FW_GROUP_PORT
N=$(rows FW_GROUP_PORT)
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_Web_out --set .COMMENT 'FWShift: Web out'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 80
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 443
N=$((N+1))
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_PLC_access --set .COMMENT 'FWShift: PLC access'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 22
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 443
N=$((N+1))
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_app-ports --set .COMMENT 'FWShift: app-ports'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 443
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 9000-9010
N=$((N+1))

# FW_INCOMING
N=$(rows FW_INCOMING)
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO udp --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 53 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT 'DNS: Name resolution'
gc --silent --set-refname "FW_INCOMING.$N.FROM_IP" fws_DNS_src
gc --silent --set-refname "FW_INCOMING.$N.IN_IP" fws_dns-servers
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO tcp --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 53 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT 'DNS: Name resolution'
gc --silent --set-refname "FW_INCOMING.$N.FROM_IP" fws_DNS_src
gc --silent --set-refname "FW_INCOMING.$N.IN_IP" fws_dns-servers
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO tcp --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 22 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT rule-2
gc --silent --set-refname "FW_INCOMING.$N.FROM_IP" fws_admin-range
gc --silent --set-refname "FW_INCOMING.$N.IN_IP" fws_dmz-servers
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO all --set .FROM_IP 10.10.200.0/24 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG yes --set .COMMENT 'Guests stay out'
gc --silent --set-refname "FW_INCOMING.$N.IN_IP" fws_Guests_stay_out_dst
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO tcp --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 10.30.1.0/24 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT 'PLC access: Operators from the office, vendor support from anywhere'
gc --silent --set-refname "FW_INCOMING.$N.FROM_IP" fws_admin-range
gc --silent --set-refname "FW_INCOMING.$N.IN_PORT" fws_PLC_access
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 443 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT 'Public web: web-1 has automatic static NAT'
gc --silent --set-refname "FW_INCOMING.$N.IN_IP" fws_Public_web_dst
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 10.20.0.10 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT 'DMZ access / Web in'
gc --silent --set-refname "FW_INCOMING.$N.IN_PORT" fws_app-ports
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 10.20.0.25 --set .IN_PORT 25 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT 'DMZ access / Mail in'
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 10.20.0.0/24 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG no --set .COMMENT 'DMZ access (cleanup of DMZ-Layer): implicit cleanup of inline layer DMZ-Layer'
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO gre --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 198.51.100.1 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT Tunnels
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT 113 --set .TARGET_REF REJECT --set .LOG yes --set .COMMENT 'No ident'
N=$((N+1))
gc --silent --goto FW_INCOMING --add-row --set .EXT_IF ext1 --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG yes --set .COMMENT 'Cleanup rule'
N=$((N+1))

# FW_OUTGOING
N=$(rows FW_OUTGOING)
gc --silent --goto FW_OUTGOING --add-row --set .PROTO udp --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 53 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT 'DNS: Name resolution'
gc --silent --set-refname "FW_OUTGOING.$N.FROM_IP" fws_DNS_src
gc --silent --set-refname "FW_OUTGOING.$N.IN_IP" fws_dns-servers
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 53 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT 'DNS: Name resolution'
gc --silent --set-refname "FW_OUTGOING.$N.FROM_IP" fws_DNS_src
gc --silent --set-refname "FW_OUTGOING.$N.IN_IP" fws_dns-servers
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 22 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT rule-2
gc --silent --set-refname "FW_OUTGOING.$N.FROM_IP" fws_admin-range
gc --silent --set-refname "FW_OUTGOING.$N.IN_IP" fws_dmz-servers
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO all --set .FROM_IP 10.10.200.0/24 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG yes --set .COMMENT 'Guests stay out'
gc --silent --set-refname "FW_OUTGOING.$N.IN_IP" fws_Guests_stay_out_dst
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 10.30.1.0/24 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT 'PLC access: Operators from the office, vendor support from anywhere'
gc --silent --set-refname "FW_OUTGOING.$N.FROM_IP" fws_admin-range
gc --silent --set-refname "FW_OUTGOING.$N.IN_PORT" fws_PLC_access
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 443 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT 'Public web: web-1 has automatic static NAT'
gc --silent --set-refname "FW_OUTGOING.$N.IN_IP" fws_Public_web_dst
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 10.20.0.10 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT 'DMZ access / Web in'
gc --silent --set-refname "FW_OUTGOING.$N.IN_PORT" fws_app-ports
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 10.20.0.25 --set .IN_PORT 25 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT 'DMZ access / Mail in'
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 10.20.0.0/24 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG no --set .COMMENT 'DMZ access (cleanup of DMZ-Layer): implicit cleanup of inline layer DMZ-Layer'
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO gre --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 198.51.100.1 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT Tunnels
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT 113 --set .TARGET_REF REJECT --set .LOG yes --set .COMMENT 'No ident'
N=$((N+1))
gc --goto FW_OUTGOING --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG yes --set .COMMENT 'Cleanup rule'
N=$((N+1))

if [ -z "$DRY_RUN" ]; then
  for v in FW_INCOMING_GLOBAL FW_OUTGOING_GLOBAL; do
    g=$(gaiconfig --get "$v" 2>/dev/null || true)
    [ "$g" = rules ] || printf 'NOTE: %s is %s: the rows take effect only with "Use the firewall ruleset below" (rules)\n' "$v" "$g" >&2
  done
fi
echo 'Done. Check the tables in the web interface (Network Security >> Packet Filter, Network >> NAT).' >&2
